import type { Static } from 'typebox';
import { createHash } from 'node:crypto';
import { Value } from 'typebox/value';
import { facetRegistry, facetRegistryDigest } from '../../../../../packages/model/src/generated/facets.ts';
import { FACETS_READ_COST, facetDefinition, facetList, facetQueryShape } from './contract.ts';
import { RELEASE_QUERY_COST } from './release-contract.ts';

// Facets are authored in model/definitions/facet-*.ts and generated by `task gen`; Main
// serves and admits them but never stores them: Filters reference Facets, data does not.

export type AdmittedFacet = Static<typeof facetDefinition>;

/** Every admitted Facet version, checked against the served contract when Main loads. */
const admittedFacets: readonly AdmittedFacet[] = Object.values(facetRegistry).map(facet => {
  if (!Value.Check(facetDefinition, facet)) throw new Error(`Generated Facet ${facet.id} breaks its contract`);
  return facet as AdmittedFacet;
});

const byRef = new Map(admittedFacets.map(facet => [facet.id, facet]));
const byName = new Map(admittedFacets.filter(facet => facet.current).map(facet => [facet.name, facet]));

/** A Facet by exact DefinitionRef, or a name read as its current version. */
export function resolveFacet(reference: string): AdmittedFacet | undefined {
  return byRef.get(reference) ?? byName.get(reference);
}

// The existing release query owner implements this complete shape, including
// translator matching on the same covered realization revision. Keep this
// descriptor paired with compiler/planner composition checks, not definitions alone.
const releaseShape: Static<typeof facetQueryShape> = {
  id: 'release-works-v1', state: 'ready',
  facets: ['release', 'releaseLanguage', 'releasePlatform', 'releaseStatus', 'releaseCompleteness', 'releaseTranslator']
    .map(name => {
      const facet = byName.get(name);
      if (!facet) throw new Error(`Executable release shape is missing its admitted ${name} Facet`);
      return facet.id;
    }),
  method: 'POST', href: '/v1/query', requestProfile: 'filter-document-v1',
  maxPageSize: RELEASE_QUERY_COST.pageSize,
  continuation: { request: 'page.continuation', response: 'result.nextCursor' },
};
const queryShapes = [releaseShape];
const digest = createHash('sha256').update(JSON.stringify([facetRegistryDigest, queryShapes])).digest('hex');
const list = { profile: 'facets-v1' as const, digest, facets: admittedFacets, queryShapes };
if (!Value.Check(facetList, list)) throw new Error('Generated Facet list breaks its contract');

/** The GET /v1/facets body: identical for every reader until the next deploy. */
export const facetListBody = JSON.stringify(list);
export const facetListTag = `"${digest}"`;
if (Buffer.byteLength(facetListBody) > FACETS_READ_COST.maxBytes) throw new Error('Facet list exceeds its byte bound');
